TASK:{"title":"SWEN3204 Software Architecture – Assignment 2: Short-Answer Questions","overview":"Answer six short questions applying architecture concepts to the CampusEats scenario. The assignment is worth 40 marks, including 4 marks for communication. Submit an individual, single-document response."}
RUBRIC:[{"id":"C1","name":"Q1 Quality attributes","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Two attributes that clearly matter most are chosen and justified from the scenario. Both scenarios have all six parts and both response measures are measurable."},{"label":"Proficient","min":3,"max":4,"desc":"Suitable attributes are chosen with some justification. Scenarios are mostly complete but one is missing a part or has a response measure that is not measurable."},{"label":"Developing","min":1,"max":2,"desc":"Attributes are named with little or no justification, or the scenarios are not in six-part form or are not measurable."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or irrelevant."}]},{"id":"C2","name":"Q2 Architectural style","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"A clear recommendation justified by at least two trade-offs that are specific to the scenario (team size, load profile, known problems). The downside of the recommendation is acknowledged."},{"label":"Proficient","min":3,"max":4,"desc":"A clear recommendation with two trade-offs, but one is generic or not linked to the scenario, or no downside is acknowledged."},{"label":"Developing","min":1,"max":2,"desc":"A recommendation with only one trade-off, or with generic textbook advantages and disadvantages only."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no recommendation."}]},{"id":"C3","name":"Q3 Availability calculation","weight":null,"max":8,"levels":[{"label":"Excellent","min":7,"max":8,"desc":"Parts (a), (b) and (c) are all correct with working shown, to the requested precision."},{"label":"Proficient","min":5,"max":6,"desc":"The method is correct throughout but there is one arithmetic or rounding slip, or exactly one part is incorrect."},{"label":"Developing","min":1,"max":4,"desc":"The series calculation is attempted but two or more parts are incorrect, or working is not shown."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no correct element."}]},{"id":"C4","name":"Q4 Resilience pattern","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"An appropriate pattern is named, its mechanism is explained correctly, it is applied to the outage, and at least one drawback or tuning consideration is given."},{"label":"Proficient","min":3,"max":4,"desc":"An appropriate pattern is named and explained correctly, but it is only loosely applied to the outage or no drawback or tuning consideration is given."},{"label":"Developing","min":1,"max":2,"desc":"A pattern is named but the explanation is incorrect or very thin."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or an unsuitable pattern."}]},{"id":"C5","name":"Q5 Consistency and availability","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Both choices are justified, the CAP theorem is used correctly, and a suitable concrete technique is named for each case."},{"label":"Proficient","min":3,"max":4,"desc":"Both choices are reasonable and techniques are named, but the CAP theorem is explained incorrectly or imprecisely, or one technique is missing."},{"label":"Developing","min":1,"max":2,"desc":"Choices are stated with little justification, or the CAP theorem is not used."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C6","name":"Q6 Architecture decision record","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"Context, Decision and Consequences are all present and specific to the scenario, with at least one positive and one negative consequence."},{"label":"Proficient","min":3,"max":4,"desc":"All three sections are present but the consequences are one-sided (no negative consequence) or the context is generic."},{"label":"Developing","min":1,"max":2,"desc":"One or more sections are missing or the record does not describe a decision."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C7","name":"Communication and format","weight":null,"max":4,"levels":[{"label":"Excellent","min":4,"max":4,"desc":"Every answer is within 150 words, terminology is precise, the required headings are used and sources are cited in IEEE style."},{"label":"Proficient","min":3,"max":3,"desc":"Clear writing, but one answer exceeds the word limit or there are minor citation or formatting problems."},{"label":"Developing","min":1,"max":2,"desc":"Several answers exceed the word limit, or the writing is hard to follow, or sources are not cited."},{"label":"Missing","min":0,"max":0,"desc":"Format requirements ignored."}]}]
MARKING:{"requirements":[{"id":"R1","met":"partial","where":"Question 1"},{"id":"R2","met":"yes","where":"Question 2"},{"id":"R3","met":"partial","where":"Question 3"},{"id":"R4","met":"partial","where":"Question 4"},{"id":"R5","met":"partial","where":"Question 5"},{"id":"R6","met":"partial","where":"Question 6"},{"id":"R7","met":"partial","where":null}],"technical_issues":[{"where":"Question 1 – Availability scenario","issue":"Response measure 'the system should stay up most of the time' is not measurable; a figure such as a percentage availability target or downtime limit is needed."},{"where":"Question 3(c)","issue":"End-to-end availability ignores the other three components in series. Only the payment pair (99.9975%) is reported. Correct result is about 99.80% availability and about 1.5 h/month downtime."},{"where":"Question 5(ii)","issue":"CAP misstated: partition tolerance is not optional in a distributed system; the choice is between consistency and availability during a partition. The answer also contradicts itself by saying it favours consistency and then selects consistency and availability."},{"where":"Question 6","issue":"No negative consequence is recorded (e.g., added infrastructure and operational complexity, delayed or duplicate delivery, need for idempotent consumers)."},{"where":"Question 4","issue":"No drawback or tuning trade-off is discussed beyond quoting an example threshold, such as false opens or the impact of the half-open wait period."},{"where":"Overall","issue":"No assumptions are stated, although the assignment requires them."}],"overall":"Solid, mostly well-argued answers with a clear recommendation and correct Q3(a)-(b). Key weaknesses: the incorrect end-to-end calculation in Q3(c), a misstated CAP explanation in Q5, a non-measurable availability response measure, a one-sided ADR, and missing assumptions. Several answers also exceed the 150-word limit.","criteria":[{"id":"C1","level":"Proficient","mark":4.0,"scale":6.0,"points":4.0,"max":6.0,"reasoning":"Performance and availability are well justified from the scenario, and the performance scenario has all six parts with a measurable response measure. The availability scenario's response measure ('stay up most of the time') is not measurable, which places this in Proficient rather than Excellent.","evidence":[{"where":"Question 1 – Availability scenario","quote":"Response measure: the system should stay up most of the time."},{"where":"Question 1 – opening paragraph","quote":"The two most important quality attributes are performance and availability, because the business depends on the lunch hour"}]},{"id":"C2","level":"Excellent","mark":5.0,"scale":6.0,"points":5.0,"max":6.0,"reasoning":"Clear modular-monolith recommendation justified by scenario-specific trade-offs: five-developer team size versus service overhead, and the single-VM and deployment-downtime problems. The downside is explicitly acknowledged. Strong answer, though the known-problems argument is more rationale than trade-off.","evidence":[{"where":"Question 2","quote":"First, team size versus operational overhead."},{"where":"Question 2","quote":"The trade-off I accept is that modules cannot be scaled independently, and a bug in one module can still crash the whole process."}]},{"id":"C3","level":"Proficient","mark":5.0,"scale":8.0,"points":5.0,"max":8.0,"reasoning":"Parts (a) and (b) are correct (99.30%, 5.0 h/month) with working shown. Part (c) is wrong: it reports only the payment-pair availability (99.9975%) and drops the other components from the end-to-end chain. Correct result is about 99.80% and 1.5 h/month. Exactly one part is incorrect, so Proficient.","evidence":[{"where":"Question 3(c)","quote":"So the new availability of placing an order is 99.9975%"},{"where":"Question 3(a)","quote":"A = 0.9995 × 0.999 × 0.9995 × 0.995 = 0.99301"}]},{"id":"C4","level":"Proficient","mark":4.0,"scale":5.0,"points":4.0,"max":5.0,"reasoning":"Circuit Breaker is an appropriate pattern and its Closed/Open/Half-Open mechanism is explained correctly. It is applied to the slow-provider outage. However, no drawback is given, and the threshold example is not discussed as a tuning consideration, so it falls short of Excellent.","evidence":[{"where":"Question 4","quote":"When failures exceed a threshold (for example 50% of calls in 10 seconds) the breaker moves to Open"},{"where":"Question 4","quote":"The Circuit Breaker pattern [2] would have contained the failure."}]},{"id":"C5","level":"Proficient","mark":3.0,"scale":6.0,"points":3.0,"max":6.0,"reasoning":"Choices are reasonable and concrete techniques are named (TTL cache, idempotency keys). The CAP explanation is incorrect: partition tolerance cannot be given up in a distributed system, and the answer says it favours consistency but then claims both consistency and availability. CAP is also not explicitly applied to menu browsing.","evidence":[{"where":"Question 5(ii)","quote":"so for payments we choose consistency and availability and give up partition tolerance"},{"where":"Question 5(i)","quote":"(for example Redis with a 60-second TTL)"}]},{"id":"C6","level":"Proficient","mark":3.0,"scale":5.0,"points":3.0,"max":5.0,"reasoning":"Context is specific (offline tablets, 4.2 s p95) and Decision is clear. Consequences list only positive outcomes; there is no negative consequence such as added queue complexity, delivery latency or the need for idempotent consumers. This is one-sided, so Proficient.","evidence":[{"where":"Question 6","quote":"Consequences: Placing an order no longer waits for the outlet, so the response time improves."}]},{"id":"C7","level":"Developing","mark":2.0,"scale":4.0,"points":2.0,"max":4.0,"reasoning":"References are in IEEE style and in-text citations are used. However, several answers (Questions 2, 4 and likely 1 and 5) appear to exceed the 150-word limit, and no assumptions section is provided. Estimated word counts are approximate.","evidence":[{"where":"Question 4","quote":"The Circuit Breaker pattern [2] would have contained the failure."},{"where":"References","quote":"[1] L. Bass, P. Clements, and R. Kazman, Software Architecture in Practice, 3rd ed."}]}]}
